const SESSION_KEY='asplayer:sessions:manual:v5.9.5', SELECT_KEY='asplayer:selected', SETTINGS_KEY='asplayer:settings:v5.2', HISTORY_KEY='asplayer:history:v5.2', CACHE_MS=8*60*60*1000;
