const tr=k=>(LABELS[lang]||LABELS.en)[k]||k;
const store=(k,v)=>{try{localStorage.setItem(k,typeof v==='string'?v:JSON.stringify(v));return true}catch(_){return false}};
const load=(k,def)=>{try{const v=localStorage.getItem(k);return v==null?def:JSON.parse(v)}catch(_){return def}};
function toast(v){const n=$('toast');n.textContent=String(v);n.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.style.display='none',4100)}
function server(){return SERVERS[selected]}
function session(){return loginPinAccepted ? sessions[server().key] : null}
function sessionPrefix(){return server().key+'|'+(session()?.user||'guest')+'|'}
function saveSessions(){
 localStorage.removeItem(SESSION_KEY);
 try{const sn=sessions[server().key];if(!sn)return ASPLAYER.clearSession();return ASPLAYER.saveSession(JSON.stringify({base:server().base,user:sn.user,pass:sn.pass,meta:sn.meta||{}}));}catch(_){return false;}
}
function restore(){localStorage.removeItem('asplayer:sessions:v5.1');const old=load(SESSION_KEY,{});if(old&&typeof old==='object')for(const s of SERVERS){const e=old[s.key];if(e&&typeof e.user==='string'&&typeof e.pass==='string'&&e.user&&e.pass)sessions[s.key]={user:e.user,pass:e.pass,meta:e.meta||{}}}selected=Math.max(0,SERVERS.findIndex(s=>s.key===localStorage.getItem(SELECT_KEY)));const cfg=load(SETTINGS_KEY,{});settings=cfg&&typeof cfg==='object'?cfg:{};if(settings.fitDefault5925!==true){settings={...settings,aspect:'contain',fitDefault5925:true};store(SETTINGS_KEY,settings)}lang=settings.language==='es'?'es':'en';preferred=['html5','native','external','ask'].includes(settings.player)?settings.player:'html5';parentHash=settings.parentHash||'';parentSalt=settings.parentSalt||'';parentEnabled=!!settings.parentEnabled&&!!parentHash;playAspect=['cover','contain','fill'].includes(settings.aspect)?settings.aspect:'contain';audioPref=['auto','en','es'].includes(settings.audioPref)?settings.audioPref:'auto';subsPref=['off','auto','en','es'].includes(settings.subsPref)?settings.subsPref:'off';autoFallback=settings.autoFallback!==false;settingsServerTarget=selected}
function saveSettings(){settings={...settings,language:lang,player:preferred,parentEnabled,parentHash,parentSalt,aspect:playAspect,audioPref,subsPref,autoFallback};store(SETTINGS_KEY,settings)}
function languageUI(){server().name=lang==='es'?'Servidor':'Server';document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(n=>{n.textContent=tr(n.dataset.i18n)});document.querySelectorAll('[data-ph]').forEach(n=>{n.placeholder=tr(n.dataset.ph)});$('login-language').value=lang;$('language').value=lang;$('preferred-player').value=preferred;$('default-aspect').value=playAspect;$('audio-language').value=audioPref;$('sub-language').value=subsPref;$('auto-fallback').checked=autoFallback;$('parent-toggle').checked=parentEnabled;renderServers();renderAccountSettings();$('server-status').textContent=server().name;updateTitle();if(active==='home')renderRecent();else if(['live','vod','series'].includes(active)){renderCats();renderItems()}}
function renderServers(){ $('servers').innerHTML=''; $('resume-button').classList.add('hidden'); return; /* legacy renderer */$('servers').innerHTML=SERVERS.map((s,i)=>`<button class="server ${i===selected?'active':''}" style="--accent:${s.color}" data-server="${i}"><span class="glyph">${s.glyph}</span><strong>${esc(s.name)}</strong><small>${sessions[s.key]?'● '+tr('saved'):tr('login')}</small></button>`).join('');$('resume-button').classList.toggle('hidden',!session())}
function displayAuth(){loginPinAccepted=false; $('access-pin').value=''; $('access-pin').type='password'; $('toggle-access-pin').textContent=tr('showPin'); $('toggle-access-pin').setAttribute('aria-pressed','false');hideModal();stopPlayer();cancelAll();unlockedCats.clear();$('auth-screen').classList.remove('hidden');$('app-shell').classList.add('hidden');$('mobilebar').classList.add('hidden');$('login-status').textContent='';$('username').value='';$('password').value='';languageUI();updateHttpWarning()}
function displayApp(){if(!session())return displayAuth();$('auth-screen').classList.add('hidden');$('app-shell').classList.remove('hidden');$('mobilebar').classList.remove('hidden');showTab('home')}
function setSelected(i){if(!SERVERS[i])return;cancelAll();selected=i;store(SELECT_KEY,server().key);renderServers();$('login-status').textContent=''}
function cancelAll(){operation++;sessionGeneration++;for(const [id,v] of pending){clearTimeout(v.timer);pending.delete(id);v.reject(Error('Cancelled'))}}
function updateTitle(){const name=active==='home'?tr('home'):tr(active);$('pagetitle').textContent=name;$('catalog-title').textContent=name;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===active))}
function showTab(tab){if(!session())return displayAuth();if(!['home','live','vod','series','settings'].includes(tab))return;operation++;active=tab;updateTitle();$('view-home').classList.toggle('hidden',tab!=='home');$('view-catalog').classList.toggle('hidden',!['live','vod','series'].includes(tab));$('view-settings').classList.toggle('hidden',tab!=='settings');if(tab==='home')warmHome();if(['live','vod','series'].includes(tab)){filter='';visible=32;category='none';$('search').value='';loadCategories(tab)}if(tab==='settings'){$('cache-status').textContent=tr('refresh8h');settingsServerTarget=selected;renderAccountSettings()}}
// All API requests are made by a native worker; no synchronous networking on the UI thread.
window.ASPLAYER_REPLY=(id,raw)=>{const v=pending.get(String(id));if(!v)return;pending.delete(String(id));clearTimeout(v.timer);try{const obj=JSON.parse(raw);if(obj&&obj.error)throw Error(String(obj.error));v.resolve(obj)}catch(e){v.reject(e)}};
function api(action='',extra={},override=null,serverOverride=null){const sn=override||session(),s=serverOverride||server();if(!sn)return Promise.reject(Error(tr('noSession')));let url=s.base+'/player_api.php?username='+encodeURIComponent(sn.user)+'&password='+encodeURIComponent(sn.pass);if(action)url+='&action='+encodeURIComponent(action);for(const [key,val] of Object.entries(extra))url+='&'+encodeURIComponent(key)+'='+encodeURIComponent(val);if(!window.ASPLAYER||typeof ASPLAYER.requestAsync!=='function')return Promise.reject(Error('Android network interface unavailable'));
 return new Promise((resolve,reject)=>{const id=String(nextId++),timer=setTimeout(()=>{pending.delete(id);reject(Error('Network timeout'))},45000);pending.set(id,{resolve,reject,timer});try{ASPLAYER.requestAsync(url,id)}catch(e){clearTimeout(timer);pending.delete(id);reject(Error('Unable to start network request'))}})}
async function login(){if(!prepareManualLogin())return;const user=$('username').value.trim(),pass=$('password').value;if(!user||!pass){$('login-status').textContent=tr('invalid');return}const b=$('login-button');b.disabled=true;b.textContent=tr('signing');$('login-status').textContent=tr('signing');const key=server().key,prev=sessions[key];try{const response=await api('',{},{user,pass});const info=response.user_info||{};if(!(info.auth===1||info.auth==='1'||info.auth===true||info.auth==='true')||['banned','disabled','expired'].includes(String(info.status||'').toLowerCase()))throw Error(tr('badLogin'));sessions[key]={user,pass,meta:{exp_date:info.exp_date||null,status:info.status||'',max_connections:info.max_connections||'',active_cons:info.active_cons||'',allowed_output_formats:Array.isArray(info.allowed_output_formats)?info.allowed_output_formats.filter(x=>typeof x==='string').slice(0,8):[]}};const persisted=saveSessions();displayApp();toast(tr(persisted?'saved':'sessionSaveFailed'))}catch(e){if(prev)sessions[key]=prev;else delete sessions[key];$('login-status').textContent=e.message}finally{b.disabled=false;b.textContent=tr('login')}}
function logout(){try{if(!ASPLAYER.clearSession()){toast(tr('sessionClearFailed'));return;}}catch(_){toast(tr('sessionClearFailed'));return;}if(!session())return displayAuth();const oldPrefix=sessionPrefix();delete sessions[server().key];saveSessions();cacheDeletePrefix(oldPrefix).catch(()=>{});displayAuth();toast(tr('closed'))}
async function openCache(){if(!('indexedDB' in window))return null;return new Promise(resolve=>{let r;try{r=indexedDB.open('asplayer-catalogs-v52',1)}catch(_){return resolve(null)};r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('catalogs'))r.result.createObjectStore('catalogs')};r.onerror=()=>resolve(null);r.onsuccess=()=>resolve(r.result)})}
async function db(){if(cacheDB===null)cacheDB=openCache();return cacheDB}
async function cacheRead(key){const d=await db();if(!d)return null;return new Promise(resolve=>{try{const r=d.transaction('catalogs','readonly').objectStore('catalogs').get(key);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>resolve(null)}catch(_){resolve(null)}})}
async function cacheWrite(key,data){const d=await db();if(!d)return;return new Promise(resolve=>{try{const tx=d.transaction('catalogs','readwrite');tx.objectStore('catalogs').put({updated:Date.now(),data},key);tx.oncomplete=()=>resolve();tx.onerror=()=>resolve()}catch(_){resolve()}})}
async function cacheDeletePrefix(prefix){const d=await db();if(!d)return;return new Promise(resolve=>{try{const tx=d.transaction('catalogs','readwrite'),s=tx.objectStore('catalogs'),req=s.openCursor();req.onsuccess=e=>{const c=e.target.result;if(c){if(!prefix||String(c.key).startsWith(prefix))c.delete();c.continue()}};tx.oncomplete=()=>resolve();tx.onerror=()=>resolve()}catch(_){resolve()}})}
async function cached(action,extra={},force=false){const key=sessionPrefix()+action+'|'+JSON.stringify(extra),value=await cacheRead(key);if(!force&&value&&Date.now()-value.updated<CACHE_MS)return value.data;try{const data=await api(action,extra);if(data&&typeof data==='object')cacheWrite(key,data).catch(()=>{});return data}catch(e){if(value&&value.data){$('sync-status').textContent=tr('cacheFallback');return value.data}throw e}}
function listKey(tab,cat){return cat==='all'?{}:{category_id:cat}}
async function loadCategories(tab,force=false){const generation=operation;cats=[];catalog=[];filtered=[];$('categories').innerHTML='<span class="tiny">'+tr('loading')+'</span>';$('cards').innerHTML='<p class="empty"><span class="spin"></span> '+tr('loading')+'</p>';$('count').textContent='';try{const data=await cached(ACTIONS[tab][0],{},force);if(generation!==operation||tab!==active)return;cats=Array.isArray(data)?data:[];renderCats();$('cards').innerHTML='<p class="empty">'+tr('chooseCategory')+'</p>'}catch(e){if(generation!==operation)return;displayCatalogError(e,()=>loadCategories(tab,true))}}
function isAdult(categoryName){return /(^|[^a-z])(adult|xxx|porn|erotic|sex|18\+|adultos|sexo|porno|er[oó]tico|onlyfans)([^a-z]|$)/i.test(String(categoryName||''))}
function renderCats(){let all=active==='live'?[{category_id:'all',category_name:tr('all')}].concat(cats):cats;all=all.filter(c=>!parentEnabled||!isAdult(c.category_name)||!!parentHash);$('categories').innerHTML=all.map(c=>`<button class="tab ${String(category)===String(c.category_id)?'active':''}" data-category="${esc(c.category_id)}">${esc(c.category_name)}${parentEnabled&&isAdult(c.category_name)?' 🔒':''}</button>`).join('')||'<span class="tiny">'+tr('noCategories')+'</span>'}
function tryCategory(id){const cat=cats.find(c=>String(c.category_id)===String(id));const run=()=>{unlockedCats.add(String(id));category=id;visible=32;filter='';$('search').value='';renderCats();loadItems();window.ASPLAYER_TV_CATEGORY?.(id)};if(parentEnabled&&cat&&isAdult(cat.category_name))return requestUnlock(run);run()}
async function loadItems(force=false){const gen=++operation,tab=active,cat=category;if(cat==='none')return;$('cards').innerHTML='<p class="empty"><span class="spin"></span> '+tr('loading')+'</p>';$('count').textContent='';try{const data=await cached(ACTIONS[tab][1],listKey(tab,cat),force);if(gen!==operation||tab!==active||cat!==category)return;if(!Array.isArray(data))throw Error(tr('error'));catalog=data;applyFilter()}catch(e){if(gen!==operation)return;displayCatalogError(e,()=>loadItems(true))}}
function displayCatalogError(e,cb){$('cards').innerHTML='<div class="empty">'+esc(e.message||tr('error'))+' <button class="ghost" id="retry-catalog">'+tr('retry')+'</button></div>';$('retry-catalog').onclick=cb;toast(tr('error'))}
function applyFilter(){filtered=catalog.filter(it=>!filter||String(it.name||it.title||'').toLowerCase().includes(filter));if(parentEnabled){filtered=filtered.filter(it=>{const c=cats.find(x=>String(x.category_id)===String(it.category_id));return !isAdult(c?.category_name)||unlockedCats.has(String(it.category_id))})}renderItems()}
function safeImage(url){const u=String(url||'');return /^https?:\/\//i.test(u)&&!/["'<>\\]/.test(u)?u:''}
function catalogPageContext(){return [sessionGeneration,operation,active,category,filter,lang].join('|')}
function catalogItemIdentity(it,i){return String(it.category_id??'')+'|'+String(it.stream_id??it.series_id??it.id??it.name??it.title??i)}
function renderCatalogTile(it,i){const img=safeImage(it.stream_icon||it.cover||it.movie_image);return `<button class="tile" data-item="${i}" title="${esc(it.name||it.title||'Untitled')}"><div class="cover">${img?`<img loading="lazy" decoding="async" src="${esc(img)}" onerror="this.style.display='none'" alt="">`:'▣'}</div><div class="caption"><strong>${esc(it.name||it.title||'Untitled')}</strong></div></button>`}
function renderItems(){if(!['live','vod','series'].includes(active))return;$('count').textContent=filtered.length+' '+tr('titles');$('loadmore').classList.add('hidden');if(window.ASPLAYER_PAGER?.mount($('cards'),filtered,renderCatalogTile,{context:catalogPageContext,identity:catalogItemIdentity,empty:'<p class="empty">'+tr('noItems')+'</p>'}))return;$('cards').innerHTML=filtered.slice(0,50).map(renderCatalogTile).join('')||'<p class="empty">'+tr('noItems')+'</p>'}
function pickItem(item,tab=active){if(!item)return;const c=cats.find(x=>String(x.category_id)===String(item.category_id));const run=()=>{if(tab==='live')return play(item,'live');if(tab==='vod')return showMovie(item);if(tab==='series')return showSeries(item)};if(parentEnabled&&isAdult(c?.category_name))return requestUnlock(run);run()}
async function warmHome(force=false){if(!session())return;const gen=sessionGeneration, key=sessionPrefix();$('sync-status').textContent=tr('syncing');$('recent-posters').innerHTML='<p class="tiny"><span class="spin"></span> '+tr('loading')+'</p>';try{const result=await Promise.allSettled([cached('get_live_categories',{},force),cached('get_vod_categories',{},force),cached('get_series_categories',{},force)]);if(gen!==sessionGeneration||key!==sessionPrefix())return;const vodCats=result[1].status==='fulfilled'&&Array.isArray(result[1].value)?result[1].value:[];if(!vodCats.length){$('recent-posters').innerHTML='<p class="muted">'+tr('cannotBrowse')+'</p>';return}const recentCat=vodCats.find(c=>/recent|new|latest|added|estreno|novedad|nueva|recien/i.test(c.category_name||''))||vodCats[0];const data=await cached('get_vod_streams',{category_id:recentCat.category_id},force);if(gen!==sessionGeneration||key!==sessionPrefix())return;recent=Array.isArray(data)?data.slice().sort((a,b)=>(Number(b.added)||0)-(Number(a.added)||0)).slice(0,20):[];renderRecent();$('sync-status').textContent=tr('refresh8h')}catch(e){if(gen===sessionGeneration)$('recent-posters').innerHTML='<p class="muted">'+tr('cannotBrowse')+'</p>';toast(tr('error'))}finally{if(gen===sessionGeneration)$('sync-status').textContent=tr('refresh8h')}}
function renderRecent(){if(!session())return;const hasDates=recent.some(x=>Number(x.added)>1000000000);const header=document.querySelector('[data-i18n="recent"]');if(header)header.textContent=hasDates?tr('recent'):tr('featured');$('recent-posters').innerHTML=recent.map((it,i)=>{const src=safeImage(it.stream_icon||it.cover||it.movie_image);return `<button class="poster" data-recent="${i}">${src?`<img src="${esc(src)}" loading="lazy" alt="" onerror="this.style.display='none'">`:'<div class="pict">▶</div>'}<strong>${esc(it.name||it.title||'Movie')}</strong></button>`}).join('')||'<p class="muted">'+tr('cannotBrowse')+'</p>'}
function showDetail(title,plot,detail){$('detail-title').textContent=title||'ASPLAYER';$('detail-subtitle').textContent=detail||tr('providerSynopsis');$('detail-plot').textContent=plot||tr('missingSynopsis');$('details-modal').classList.remove('hidden');$('detail-actions').innerHTML='';$('episodes').innerHTML=''}
function synopsisText(...sources){for(const source of sources){for(const key of ['plot','description','overview','synopsis','summary','plot_outline']){const value=source?.[key];if(typeof value!=='string')continue;const text=value.trim();if(text&&text!==tr('missingSynopsis')&&!/^(?:[\s.\-]+|n\/?a|null|undefined|none|no (?:plot|description|synopsis)(?: available)?|sin (?:sinopsis|descripci[oó]n)|no disponible)[.!]?$/i.test(text))return text}}return ''}
function detailInfo(data){const info=Array.isArray(data?.info)?data.info[0]:data?.info;return info&&typeof info==='object'?info:{}}
