function rememberPlay(mode,it){const key=HISTORY_KEY,all=load(key,{});const p=sessionPrefix();let h=all[p];if(!h||typeof h!=='object')h={live:[],vod:[],series:[]};let arr=Array.isArray(h[mode])?h[mode]:[];const id=String(it.stream_id||it.series_id||it.id||it.title||it.name);arr=arr.filter(x=>x.id!==id);arr.unshift({id,title:String(it.name||it.title||'').slice(0,100),watchedAt:Date.now()});h[mode]=arr.slice(0,400);all[p]=h;store(key,all)}
function play(it,mode){
 const sn=session();if(!sn){toast(tr('noSession'));return}
 let path,id,ext;
 if(mode==='live'){path='live';id=it.stream_id;ext='m3u8'}
 else if(mode==='vod'){path='movie';id=it.stream_id;ext=String(it.container_extension||'mp4').replace(/[^a-z0-9]/ig,'')||'mp4'}
 else{path='series';id=it.id||it.stream_id;ext=String(it.container_extension||'mp4').replace(/[^a-z0-9]/ig,'')||'mp4'}
 if(!id)return toast(tr('error'));
 const url=server().base+'/'+path+'/'+encodeURIComponent(sn.user)+'/'+encodeURIComponent(sn.pass)+'/'+encodeURIComponent(id)+'.'+ext;
 playback={url,ext,mode,title:it.title||it.name||'ASPLAYER'};rememberPlay(mode,it);
 if(preferred==='external')return externalPlay(url);
 if(preferred==='native')return nativePlay(url);
 if(preferred==='ask')return showChoice();
 openPlayer();
}
function nativePlay(url){try{window.ASPLAYER?.play(url)}catch(_){toast(tr('playerFailure'))}}
function externalPlay(url){try{window.ASPLAYER?.playExternal(url)}catch(_){toast(tr('playerFailure'))}}
function showChoice(){$('player-hint').textContent=tr('unsupported');$('player-choice').classList.remove('hidden')}
function stopPlayer(){clearTimeout(controlsTimer);playerRequest++;const video=$('video');try{video.pause();video.removeAttribute('src');video.load()}catch(_){}$('modern-player').classList.add('hidden');$('modern-player').classList.remove('controls-hidden');$('player-track-panel').classList.add('hidden');$('player-choice').classList.add('hidden')}
function showControls(){const n=$('modern-player');if(n.classList.contains('hidden'))return;n.classList.remove('controls-hidden');clearTimeout(controlsTimer);controlsTimer=setTimeout(()=>{if(!n.classList.contains('hidden')&&$('player-track-panel').classList.contains('hidden')&&!$('video').paused)n.classList.add('controls-hidden')},3000)}
function openPlayer(){if(!playback)return;const video=$('video');const request=++playerRequest;playbackErrors=0;$('player-choice').classList.add('hidden');$('modern-player').classList.remove('hidden');$('player-track-panel').classList.add('hidden');$('playing-title').textContent=playback.title;$('player-message').textContent='';video.style.objectFit=playAspect;showControls();
 // HLS needs native OS support in this standalone build; use working Android player if the WebView does not expose it.
 if(playback.ext.toLowerCase()==='m3u8'&&!video.canPlayType('application/vnd.apple.mpegurl')&&!video.canPlayType('application/x-mpegURL')){
  if(autoFallback){stopPlayer();nativePlay(playback.url);return}
  $('player-message').textContent=tr('unsupported')
 }
 video.src=playback.url;video.load();Promise.resolve(video.play()).catch(()=>{if(request!==playerRequest)return;onPlayerFailure()});updateTracks()
}
function onPlayerFailure(){if(!playback||$('modern-player').classList.contains('hidden'))return;if(++playbackErrors>1)return;$('player-message').textContent=tr('playerFailure');showControls();if(autoFallback){const url=playback.url;stopPlayer();nativePlay(url);toast(tr('fallbackUsed'))}}
function fmtTime(sec){if(!isFinite(sec))return'00:00';let n=Math.floor(sec);const h=Math.floor(n/3600);n%=3600;return(h?String(h).padStart(2,'0')+':':'')+String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function matchLang(track,requested){const s=String(track.language||track.label||'').toLowerCase();return requested==='es'? /(^|[^a-z])(es|esp|spa|spanish|español)/i.test(s):/(^|[^a-z])(en|eng|english|ingl[eé]s)/i.test(s)}
function updateTracks(){const video=$('video'),as=$('player-audio'),subs=$('player-subs');let audio=video.audioTracks||[],texts=video.textTracks||[];const oldAudio=as.value,oldSubs=subs.value;as.innerHTML='<option value="auto">'+tr('automatic')+'</option>';subs.innerHTML='<option value="off">'+tr('off')+'</option>';
 for(let i=0;i<audio.length;i++){const t=audio[i],o=document.createElement('option');o.value=String(i);o.textContent=t.label||t.language||'Audio '+(i+1);as.appendChild(o)}
 for(let i=0;i<texts.length;i++){const t=texts[i],o=document.createElement('option');o.value=String(i);o.textContent=t.label||t.language||'Subtitle '+(i+1);subs.appendChild(o)}
 const preferredAudio=Array.from(audio).findIndex(t=>audioPref!=='auto'&&matchLang(t,audioPref));const preferredSubs=Array.from(texts).findIndex(t=>subsPref!=='off'&&subsPref!=='auto'&&matchLang(t,subsPref));
 as.value=Array.from(as.options).some(o=>o.value===oldAudio)&&oldAudio!=='auto'?oldAudio:(preferredAudio>=0?String(preferredAudio):'auto');subs.value=Array.from(subs.options).some(o=>o.value===oldSubs)&&oldSubs!=='off'?oldSubs:(preferredSubs>=0?String(preferredSubs):(subsPref==='auto'&&texts.length?'0':'off'));applyAudio();applySubs();$('tracks-state').textContent=(audio.length+texts.length)?tr('tracksFound'):tr('noTracks')
}
function applyAudio(){const tracks=$('video').audioTracks||[];for(let i=0;i<tracks.length;i++)try{tracks[i].enabled=($('player-audio').value==='auto'?i===0:i===Number($('player-audio').value))}catch(_){}}
