async function hashPin(pin,salt){if(!window.crypto?.subtle||!window.TextEncoder)return null;const enc=new TextEncoder();let data=enc.encode('ASPLAYER:parent:'+salt+':'+pin);for(let i=0;i<300;i++){data=new Uint8Array(await crypto.subtle.digest('SHA-256',data))}return Array.from(data).map(v=>v.toString(16).padStart(2,'0')).join('')}
function requestUnlock(cb){if(!parentEnabled||!parentHash)return cb();unlockNext=cb;$('parent-modal').classList.remove('hidden');$('unlock-pin').value='';$('unlock-message').textContent='';$('unlock-pin').focus()}
async function unlock(){if(!unlockNext)return;const code=$('unlock-pin').value;const h=await hashPin(code,parentSalt);if(!h||h!==parentHash){$('unlock-message').textContent=tr('invalidPin');return}const cb=unlockNext;unlockNext=null;$('parent-modal').classList.add('hidden');cb()}
async function savePin(){const pin=$('parent-pin').value;if(!/^\d{4,8}$/.test(pin))return toast(tr('pinNeed'));const salt=String(Date.now())+Math.random().toString(36).slice(2);const hash=await hashPin(pin,salt);if(!hash)return toast(tr('pinUnsupported'));parentHash=hash;parentSalt=salt;parentEnabled=true;$('parent-toggle').checked=true;$('parent-pin').value='';saveSettings();toast(tr('pinSaved'))}
